    @inline(__always)
    private func checkLoadFirstWideningFromInt16BeforeGuardPageConstantCount(_ count: Int) {
        let mismatches = Mismatches(
            "loadFirstWidening from Int16 with count \(count) before a guard page"
        )
        let fromInputs = Inputs.buffers(Int16.self, count: H.laneCount, seed: 0x1144_F442_0C1D_F188)
        for from in fromInputs {
            let (portResult, referenceResult) = unsafe withGuardedLanes(Array(from.prefix(count))) {
                source in
                (
                    unsafe H.loadFirstWidening(from: source, count: count),
                    unsafe H.Vector(
                        raw: HighwayReference.loadFirstWideningI16ToI32(
                            source,
                            min(count, H.laneCount)
                        )
                    )
                )
            }.result
            mismatches.check(portResult, referenceResult, "from: \(describe(from))")
        }
        mismatches.record()
    }

